"""Generate results/ml/CONFORMAL.md from the conformal CSVs (no number is typed by hand): `python -m oxydrop_ml.conformal report --res ../results/ml`."""
from __future__ import annotations

import os

import numpy as np
import pandas as pd

from . import conformal as C

SYS_NAME = {'final': 'HYBRID_FINAL (inner-fold selected pipeline)', 'deployed_R': 'deployed pipeline R (fixed; exploratory)', 'chain_v1': 'v1 chain alone (control)'}


def pct(x, d=1):
    return 'n/a' if not np.isfinite(x) else f'{100 * x:.{d}f}%'


def ci(r, k, d=1):
    return f'{pct(r[k], d)} [{pct(r[k + "_lo"], d)}, {pct(r[k + "_hi"], d)}]'


def pp(x, d=1):
    return 'n/a' if not np.isfinite(x) else f'{100 * x:+.{d}f}'


def table(rows, header):
    out = ['| ' + ' | '.join(header) + ' |', '|' + '---|' * len(header)]
    out += ['| ' + ' | '.join(str(c) for c in r) + ' |' for r in rows]
    return '\n'.join(out)


def at(curve, system, method, alpha):
    d = curve[(curve.system == system) & (curve.method == method) & np.isclose(curve.param, alpha)]
    return d.iloc[0]


def verdict(diff, lo, hi):
    if np.isfinite(lo) and np.isfinite(hi):
        return 'better (interval excludes 0)' if lo > 0 else ('worse (interval excludes 0)' if hi < 0 else 'tie (interval contains 0)')
    return 'n/a'


def report(res):
    cu = pd.read_csv(os.path.join(res, 'conformal_curve.csv'))
    ma = pd.read_csv(os.path.join(res, 'conformal_matched.csv'))
    pe = pd.read_csv(os.path.join(res, 'conformal_per_person.csv'))
    ref = pd.read_csv(os.path.join(res, 'conformal_reference_bands.csv')).set_index('system')
    ca = pd.read_csv(os.path.join(res, 'conformal_calibration.csv')).set_index('system')
    sh = pd.read_csv(os.path.join(res, 'conformal_shipped.csv'))
    rk = pd.read_csv(os.path.join(res, 'conformal_ranked.csv'))
    th = pd.read_csv(os.path.join(res, 'conformal_thresholds.csv'))
    A = C.HEADLINE
    L = []
    L.append('# OxyDrop conformal 3-state output (FEAT-007)\n')
    L.append('*Generated by `python/oxydrop_ml/conformal_md.py` from the `results/ml/conformal_*.csv` files; do not edit by hand. Research prototype, not a medical device.*\n')
    L.append('Protocol: `python/oxydrop_ml/PREREGISTRATION.md` with `amendments/AMENDMENT_5_conformal_openox.md` (committed before any conformal score was computed). Every result here is a secondary, **exploratory** analysis; no pre-registered win is claimed.\n')
    L.append('## What is evaluated\n')
    L.append('The output of the model is one of three states: **Normal**, **Possible low oxygen (re-check with a pulse oximeter)**, **Unsure (re-measure)**. A window gets a prediction set from class-conditional (Mondrian) split conformal prediction on the final logit `z`; a set `{0}` is Normal, `{1}` is Possible low oxygen, `{0, 1}` or `{}` is Unsure. The only abstention is Unsure.\n')
    L.append('Nested protocol: for each of the 6 Hoffman people (leave-one-person-out), the thresholds come from the other five people only. Their windows are scored out of fold by the same pipeline (CNN logits from fits that exclude both the person and the evaluated person, meta-learner fit on four people). The evaluated person never touches its own thresholds. Windows with t >= 60 s: 5,644 windows (3,244 hypoxic, 2,400 normal). Intervals are 95 % person bootstraps (people resampled, B = 2000), so with six people they are wide.\n')
    n = int(ca.loc['final', 'n_windows'])
    prev = float(ca.loc['final', 'prevalence'])
    L.append(f'Pooled prevalence of hypoxic windows {pct(prev)}. Plain accuracy is the metric of the v1 and v2 reference numbers (93.9 % at 84.4 % coverage, 94.7 % at 68.0 %); balanced accuracy, sensitivity and specificity are given beside it because the classes are not balanced.\n')
    # headline
    L.append(f'## Headline: miscoverage target alpha = {A:.2f} (declared before any result), Mondrian\n')
    rows = []
    for s in C.SYSTEMS:
        r = at(cu, s, 'mondrian', A)
        rows.append([SYS_NAME[s], ci(r, 'coverage'), ci(r, 'acc'), pct(r.bacc_answered), f'{pct(r.sens_answered)} / {pct(r.spec_answered)}', ci(r, 'alert_share_all'), pct(r.confident_miss), pct(r.confident_false_alarm),
                     f'{pct(r.share_normal)} / {pct(r.share_low)} / {pct(r.share_unsure)}'])
    L.append(table(rows, ['pipeline', 'coverage (answered)', 'accuracy on answered', 'balanced acc.', 'sens / spec (answered)', 'share of ALL hypoxic windows alerted', 'hypoxic windows called Normal', 'normal windows called Low', 'Normal / Low / Unsure share']))
    L.append('')
    r = at(cu, 'final', 'mondrian', A)
    L.append(f'For `HYBRID_FINAL` at alpha = {A:.2f}: {pct(r.coverage)} of windows are answered with {pct(r.acc)} accuracy; {pct(r.alert_share_all)} of ALL hypoxic windows receive a Possible-low-oxygen alert, {pct(r.unsure_of_hypoxic)} of them are Unsure and {pct(r.confident_miss)} are confidently called Normal. Without abstention the same score has accuracy {pct(at(cu, "final", "band", 0.0).acc)} and alerts {pct(at(cu, "final", "band", 0.0).alert_share_all)} of hypoxic windows.\n')
    # coverage vs target
    L.append('## Empirical coverage next to the target\n')
    L.append('The conformal guarantee is that a window\'s set contains its true label with probability >= 1 - alpha, per class for Mondrian, if calibration and test windows are exchangeable. Windows of one person overlap by 80 % and people differ, so the guarantee is only approximate across people. Held-out values (pooled over the six evaluated people):\n')
    rows = []
    for a in (0.02, 0.05, 0.10, 0.15):
        for s in ('final', 'deployed_R', 'chain_v1'):
            r = at(cu, s, 'mondrian', a)
            rows.append([f'{a:.2f}', pct(1 - a, 0), SYS_NAME[s].split(' (')[0], ci(r, 'set_cov_hypoxic'), ci(r, 'set_cov_normal'), 'yes' if (r.set_cov_hypoxic >= 1 - a - 0.005 and r.set_cov_normal >= 1 - a - 0.005) else 'no, below target'])
    L.append(table(rows, ['alpha', 'target 1 - alpha', 'pipeline', 'set coverage, hypoxic windows', 'set coverage, normal windows', 'both classes at target']))
    L.append('')
    miss = [(s, a) for s in C.SYSTEMS for a in (0.02, 0.05, 0.10, 0.15) for r in [at(cu, s, 'mondrian', a)] if not (r.set_cov_hypoxic >= 1 - a - 0.005 and r.set_cov_normal >= 1 - a - 0.005)]
    L.append(f'{len(miss)} of 12 (pipeline, alpha) cells are below target by more than half a point in at least one class; the largest shortfall is {100 * (max(max(1 - a - at(cu, s, "mondrian", a).set_cov_hypoxic, 1 - a - at(cu, s, "mondrian", a).set_cov_normal) for s, a in [(s, a) for s in C.SYSTEMS for a in (0.02, 0.05, 0.10, 0.15)])):.1f} points of coverage. Per-person thresholds are in `conformal_thresholds.csv`.\n')
    # curve
    L.append('## Coverage-versus-accuracy curve\n')
    L.append('Full curves (alpha 0.005 to 0.5, Mondrian and marginal, plus the fixed band `|p - 0.5| < delta`, with bootstrap intervals) are in `conformal_curve.csv`; confidence-ranked selective curves in `conformal_ranked.csv`. Conformal coverage first rises with alpha, then falls again once the two class thresholds cross (the middle band then contains empty sets). Rows past that point are labelled `past_crossing` in the CSV and are not used for matching.\n')
    rows = []
    for a in (0.02, 0.05, 0.10, 0.15):
        for s in ('final', 'deployed_R', 'chain_v1'):
            r = at(cu, s, 'mondrian', a)
            rows.append([f'{a:.2f}', SYS_NAME[s].split(' (')[0], ci(r, 'coverage'), ci(r, 'acc'), pct(r.bacc_answered), ci(r, 'alert_share_all')])
    L.append(table(rows, ['alpha (Mondrian)', 'pipeline', 'coverage', 'accuracy on answered', 'balanced accuracy', 'share of ALL hypoxic alerted']))
    L.append('')
    rows = []
    for s in ('final', 'deployed_R', 'chain_v1'):
        for d in (0.0, 0.10, 0.20):
            r = at(cu, s, 'band', d)
            rows.append([SYS_NAME[s].split(' (')[0], f'|p - 0.5| < {d:.2f}', ci(r, 'coverage'), ci(r, 'acc'), ci(r, 'alert_share_all')])
    L.append('Fixed abstain band on the same scores (no calibration set; delta = 0.10 is the shipped v1 rule):\n')
    L.append(table(rows, ['pipeline', 'rule', 'coverage', 'accuracy on answered', 'share of ALL hypoxic alerted']))
    L.append('')
    # matched coverage
    L.append('## Matched coverage against v1 and v2\n')
    rr = ref
    L.append(f'References on the same 5,644 windows (from `baseline_P1_hoffman.csv`; they reproduce `results/eval_v1_vs_v2.csv`): **v1 shipped band** accuracy {ci(rr.loc["v1_shipped_band"], "acc")} at coverage {pct(rr.loc["v1_shipped_band"].coverage)}, alerts {pct(rr.loc["v1_shipped_band"].alert_share_all)} of hypoxic windows; **v2 (no-lock windows abstain, band)** accuracy {ci(rr.loc["v2_shipped_band"], "acc")} at coverage {pct(rr.loc["v2_shipped_band"].coverage)}. Rows below read each system at exactly that coverage: nested conformal by interpolation along alpha, and a confidence-ranked control (top windows by `|z|`, coverage exact, not nested, so slightly optimistic).\n')
    rows = []
    for _, r in ma.iterrows():
        rows.append([r.reference, pct(r.target_coverage), SYS_NAME[r.system].split(' (')[0], r.variant, ci(r, 'acc'), pct(r.reference_acc), f'{pp(r.diff_acc)} [{pp(r.diff_lo)}, {pp(r.diff_hi)}]', verdict(r.diff_acc, r.diff_lo, r.diff_hi), pct(r.alert_share_all)])
    L.append(table(rows, ['reference', 'matched coverage', 'pipeline', 'variant', 'accuracy [95% CI]', 'reference accuracy', 'difference in points [95% CI]', 'verdict', 'share of ALL hypoxic alerted']))
    L.append('')
    f = ma[(ma.system == 'final') & (ma.variant == 'conformal_mondrian')].set_index('reference')
    c1 = ma[(ma.system == 'chain_v1') & (ma.variant == 'conformal_mondrian')].set_index('reference')
    d = ma[(ma.system == 'deployed_R') & (ma.variant == 'conformal_mondrian')].set_index('reference')
    L.append('Reading, computed from the table:\n')
    L.append(f'* **The hybrid CNN does not beat v1 at matched coverage.** `HYBRID_FINAL` with nested Mondrian conformal reads {pct(f.loc["v1"].acc)} at v1\'s coverage of {pct(f.loc["v1"].target_coverage)} against {pct(f.loc["v1"].reference_acc)} for the v1 shipped band: {pp(f.loc["v1"].diff_acc)} points [{pp(f.loc["v1"].diff_lo)}, {pp(f.loc["v1"].diff_hi)}], {verdict(f.loc["v1"].diff_acc, f.loc["v1"].diff_lo, f.loc["v1"].diff_hi)}. Against v2 at {pct(f.loc["v2"].target_coverage)} coverage: {pp(f.loc["v2"].diff_acc)} points [{pp(f.loc["v2"].diff_lo)}, {pp(f.loc["v2"].diff_hi)}].')
    L.append(f'* The deployed pipeline R (fixed, exploratory) reads {pct(d.loc["v1"].acc)} at v1\'s coverage ({pp(d.loc["v1"].diff_acc)} points [{pp(d.loc["v1"].diff_lo)}, {pp(d.loc["v1"].diff_hi)}]) and {pct(d.loc["v2"].acc)} at v2\'s ({pp(d.loc["v2"].diff_acc)} [{pp(d.loc["v2"].diff_lo)}, {pp(d.loc["v2"].diff_hi)}]).')
    L.append(f'* The same conformal procedure on the v1 chain alone reads {pct(c1.loc["v1"].acc)} at v1\'s coverage ({pp(c1.loc["v1"].diff_acc)} points [{pp(c1.loc["v1"].diff_lo)}, {pp(c1.loc["v1"].diff_hi)}] against the hand-set band) and {pct(c1.loc["v2"].acc)} at v2\'s coverage ({pp(c1.loc["v2"].diff_acc)} [{pp(c1.loc["v2"].diff_lo)}, {pp(c1.loc["v2"].diff_hi)}]). On the incumbent score the calibrated output is within {abs(100 * c1.loc["v1"].diff_acc):.1f} points of the hand-set band at the same coverage ({verdict(c1.loc["v1"].diff_acc, c1.loc["v1"].diff_lo, c1.loc["v1"].diff_hi)}), so the conformal step replaces a hand-set threshold with a calibrated one at little cost in accuracy; the gap to v1 comes from the hybrid score, not from the conformal step.')
    L.append(f'* AUROC over all windows: hybrid {ca.loc["final", "auroc_all"]:.3f}, deployed R {ca.loc["deployed_R", "auroc_all"]:.3f}, v1 chain {ca.loc["chain_v1", "auroc_all"]:.3f}. ECE of the probability `sigmoid(z)`: hybrid {ca.loc["final", "ece_all_windows"]:.3f} (answered windows at alpha = {A:.2f}: {ca.loc["final", "ece_answered_mondrian_alpha010"]:.3f}), deployed R {ca.loc["deployed_R", "ece_all_windows"]:.3f}, v1 chain {ca.loc["chain_v1", "ece_all_windows"]:.3f} (the chain is not calibrated, only ranked well).')
    L.append('')
    # per person
    L.append(f'## Per person (alpha = {A:.2f}, Mondrian, `HYBRID_FINAL`)\n')
    rows = []
    for _, r in pe[(pe.system == 'final') & (pe.method == 'mondrian') & np.isclose(pe.alpha, A)].iterrows():
        rows.append([r.person, int(r.n), pct(r.coverage), pct(r.acc), pct(r.alert_share_all), pct(r.confident_miss), pct(r.set_cov_hypoxic), pct(r.set_cov_normal), pct(r.share_unsure)])
    L.append(table(rows, ['person', 'windows', 'coverage', 'accuracy answered', 'ALL hypoxic alerted', 'hypoxic called Normal', 'set cov. hypoxic', 'set cov. normal', 'Unsure share']))
    p = pe[(pe.system == 'final') & (pe.method == 'mondrian') & np.isclose(pe.alpha, A)]
    L.append(f'\nPer-person coverage ranges from {pct(p.coverage.min())} to {pct(p.coverage.max())} and accuracy on answered windows from {pct(p.acc.min())} to {pct(p.acc.max())}; the share of hypoxic windows called Normal reaches {pct(p.confident_miss.max())} for the worst person ({p.person.values[int(np.argmax(p.confident_miss.values))]}), against a target of {pct(A, 0)}; the set coverage of the normal windows falls to {pct(p.set_cov_normal.min())} for {p.person.values[int(np.argmin(p.set_cov_normal.values))]}. The pooled coverage hides these person-level failures: the guarantee is marginal over windows pooled across people, not per person. Per-person rows for alpha 0.05 and 0.20 and the other pipelines are in `conformal_per_person.csv`.\n')
    # shipped
    L.append('## Parameters shipped to the app (`app/data/conformal.json`)\n')
    L.append('Thresholds on the logit `z` of the deployed pipeline, fit on the pooled out-of-fold windows of all six Hoffman people (leave-one-person-out meta-learner). They are not evaluated on any person (nobody is left out); the nested rows above are their evaluation. Rule: Normal if `z < min(t0, t1)`, Possible low oxygen if `z > max(t0, t1)`, Unsure in between.\n')
    rows = [[r.method, f'{r.alpha:.2f}', f'{r.t0:.3f}', f'{r.t1:.3f}', 'yes' if r.past_crossing else 'no', pct(r.pooled_in_sample_coverage), pct(r.pooled_in_sample_acc)] for _, r in sh.iterrows()]
    L.append(table(rows, ['method', 'alpha', 't0 (contains Normal if z <= t0)', 't1 (contains Low if z >= t1)', 'past crossing', 'in-sample coverage', 'in-sample accuracy']))
    L.append('')
    L.append('## Limits\n')
    L.append('* Six people, five of whom are scored by a model fit on five. Every interval is wide, and no difference above is a pre-registered win.\n* Coverage guarantees assume exchangeability. Windows overlap by 80 % and people differ, so held-out set coverage sits slightly below target in some cells (table above).\n* The windows come from the Hoffman phones. Nothing here is tuned to a phone; untested Android and other phones are a limitation.\n* Accuracy at matched coverage depends on the class mix of the six people (57.5 % hypoxic windows) and is not the pre-registered time-matched metric.\n* v1 and v2 reference numbers are the shipped bands of those models on the same windows; the conformal rows are nested, the confidence-ranked control rows are not.\n')
    L.append('## Reproduce\n')
    L.append('```\nbash scripts/reproduce_ml.sh conformal-calib     # needs the FEAT-008 run tables: scores/conformal_inputs_hoffman.csv\nbash scripts/reproduce_ml.sh conformal           # the nested evaluation, CONFORMAL.md and app/data/conformal.json from the score CSVs\n```\n')
    open(os.path.join(res, 'CONFORMAL.md'), 'w').write('\n'.join(L))
    print('wrote', os.path.join(res, 'CONFORMAL.md'))
